pragma solidity ^0.8.36;

contract StorageHazards {
    struct S { uint256 a; uint256 b; }
    S x;
    S y;
    bytes data;

    function storageCopies() public {
        (x, y) = (y, x);
        uint256 z;
        ((x, y), z) = ((y, x), 0);
        ((((x, y))), z) = ((((y, x))), 0);
    }

    function byteCopies() public {
        (data.push(), data[0]) = (0, 0);
        (((data.push())), (data.push())) = (0, 0);
        bytes storage aliasData = data;
        (data.push(), aliasData.push()) = (0, 0);
    }
}

contract LargeStorage {
    struct Huge { uint256[2**255] cells; }
    function inspect(Huge storage) internal {}
}

contract AssemblyBase {
    constructor() { assembly { pop(0) } }
}

contract AssemblyChild is AssemblyBase {}

contract RuntimeProbe {
    function inspect() external pure returns (uint256) {
        return type(AssemblyBase).runtimeCode.length +
            type(AssemblyChild).runtimeCode.length +
            type(AssemblyBase).creationCode.length;
    }
}

contract ThisDuringConstruction {
    function ping() external pure {}
    constructor() {
        this.ping();
        (this).ping();
        ((this)).ping();
    }
}

library SelfCall {
    using SelfCall for *;
    function invoke() public pure returns (uint256 result) { return result.bump(); }
    function bump(uint256 value) public pure returns (uint256) { return value; }
}

contract EvaluationDiagnostics {
    uint256 constant ZERO = 0;
    function arithmetic(uint256 unused) external pure returns (uint256 result) {
        uint256 local;
        1 / ZERO;
        result = addmod(1, 2, ZERO);
    }
}
